function kb.weatherStrength(jq)
local kq=kb.fx(jq)
local lq=kq.dmg/kq.cd/kq.hp/kq.speed*(1+(kq.range-1)/2)
for mq,nq in pairs(kq.kinds)do
lq=lq*(1+bb.rogueShare(mq)*nq)
end
if kq.ice>0 then
local oq=bb.rogueShare(eEd[1876])
lq=lq*(oq+(1-oq)/(1-kq.ice+kq.ice/fb.modFactor(eEd[2005])))
end
if kq.fly>0 then
lq=lq*(1-kq.fly*0.5)
end
if kq.noCC then
lq=lq*0.95
end
if kq.shroud then
lq=lq*0.9
end
if kq.zap then
lq=lq*0.85
end
return lq/kb.weatherK(jq)
end
kb.WEATHER_K_MIN,kb.WEATHER_K_MAX,kb.WEATHER_K_RUNS=0.5,4,10
function kb.weatherK(pq)
local qq=pq and type(P.hunt)==eEd[1741]and type(P.hunt.wk)==eEd[1741]and P.hunt.wk[tostring(pq)]or nil
return type(qq)==eEd[1741]and tonumber(qq.k)or 1
end
function kb.weatherLearn()
if bb.withOthers or#game:GetService(eEd[645]):GetPlayers()>1 then
return
end
local rq=bb.huntWeather or kb.weatherNow()
local sq,tq=bb.pred,bb.calRun
if not rq or type(sq)~=eEd[1741]or type(tq)~=eEd[1741]then
return
end
local function uq(vq,wq)
return type(vq)==eEd[1741]and tonumber(vq[wq]or vq[tostring(wq)])or nil
end
local xq={}
for yq=2,bb.wave()do
local zq,Aq=uq(tq.alive,yq),uq(sq.aliveAt,yq)
if zq and Aq and zq>0 and Aq>0 then
table.insert(xq,zq/Aq)
end
end
if#xq<3 then
return
end
table.sort(xq)
local Bq=xq[math.ceil(#xq/2)]
P.hunt.wk=type(P.hunt.wk)==eEd[1741]and P.hunt.wk or{}
local Cq=P.hunt.wk[tostring(rq)]
local Dq=math.min(kb.WEATHER_K_RUNS-1,type(Cq)==eEd[1741]and tonumber(Cq.n)or 0)
local Eq=kb.weatherK(rq)
local Fq=math.max(1,Dq)
local Gq=math.exp((Fq*math.log(Eq)+math.log(Eq*Bq))/(Fq+1))
Gq=U.clamp(Gq,kb.WEATHER_K_MIN,kb.WEATHER_K_MAX)
bb.wkWas={w=tostring(rq),old=Cq}
P.hunt.wk[tostring(rq)]={k=Gq,n=(type(Cq)==eEd[1741]and tonumber(Cq.n)or 0)+1,at=os.time()}
F.log(1,eEd[2006],string.format(eEd[2007],tostring(rq),Bq,tostring(rq),Gq,Eq,P.hunt.wk[tostring(rq)].n))
end
