VQ=VQ+WQ*0.5
local ZQ=V.rows(PQ.unit_id)
local _Q=ZQ and ZQ[ZQ.max]
local aR=(_Q and tonumber(_Q.cd)or 0)*V.mult(PQ,eEd[1906])
for bR,cR in pairs(RQ._unique_relic_effects or{})do
local dR=type(cR.params)==eEd[1741]and cR.params or{}
if cR.id==eEd[2452]then
local eR=math.min(1,(tonumber(dR.extra_damage)or 0)*aR/math.max(1,tonumber(dR.time_interval)or 40))
local fR=V.DRONES and V.DRONES[PQ.unit_id]
if fR and fR.late and aR>0 then
local gR=1/aR
eR=eR*gR/(gR+(tonumber(fR.max)or 0)*(tonumber(fR.late.dmg)or 0)*(tonumber(fR.hits)or 1)/math.max(0.1,tonumber(fR.late.cd)or 4))
end
VQ=VQ+eR
elseif cR.id==eEd[2453]then
VQ=VQ+(tonumber(dR.dmg_buff)or 0)*0.25
elseif cR.id==eEd[2454]then
VQ=VQ+(tonumber(dR.dmg_buff)or 0)*WQ
elseif cR.id==eEd[2455]then
if TQ.magic then
VQ=0
else
VQ=VQ+(tonumber(dR.dmg_buff)or 0)*0.3
end
elseif cR.id==eEd[2456]then
if TQ.water_damage then
VQ=VQ+0.05
end
end
end
return VQ
end
