if not JR[QR.it.uuid]and not(RR and KR[QR.it.item_id])then
JR[QR.it.uuid]=true
if RR then
KR[QR.it.item_id]=true
end
IR[OR.e.uuid]=QR.it.uuid
LR(MR+1,NR+QR.w+(QR.it.uuid==OR.e.u._equipped_relic and 0.01 or 0))
IR[OR.e.uuid]=nil
JR[QR.it.uuid]=nil
if RR then
KR[QR.it.item_id]=nil
end
end
end
end
LR(1,0)
local SR,TR=0,{}
for UR,VR in ipairs(mR)do
local WR=VR.e.u._equipped_relic and hR.inventory:get_item_by_uuid(VR.e.u._equipped_relic)
local XR=WR and jb.relicWorth(VR.e.u,WR)*VR.share*100 or 0
SR=SR+XR
