local ZR=YR and jb.relicWorth(VR.e.u,YR)*VR.share*100 or 0
table.insert(TR,string.format(eEd[2459],V.name(VR.e.id),WR and(N.Items[WR.item_id]or{}).name or eEd[2046],XR,YR and(N.Items[YR.item_id]or{}).name or eEd[2046],ZR))
end
return GR,HR-SR,TR,mR
end
