function jb.xpGuess(IT)
local JT=IT.level and N.Levels[IT.level]
if not JT then
return 0
end
local KT=math.min(9,tonumber(JT.story_world_rank)or tonumber(IT.rank)or 9)
local LT=tonumber(JT.story_level_rank)or 6
local NT=(IT.kind==eEd[1780]and 1.5 or 1)*(KT>5 and 2 or 1)
local OT=2.1564^(KT-1)*(40+10*LT)/NT
if IT.kind==eEd[1760]then
OT=3*30*2.1564^(KT-1)/NT
end
local PT=KT>=9 and 0.3 or(KT>=7 and 0.5 or 1)
return OT*PT*6
end
