function eb.upgradeGain(lib,mib,nib,oib,pib,qib)
local rib,sib=mib[nib],mib[nib+1]
local tib=(rib.cd>0 and rib.damage/rib.cd or 0)
local uib=(sib.cd>0 and sib.damage/sib.cd or 0)*V.aoe(sib.atk,sib.range)/math.max(0.3,V.aoe(rib.atk,rib.range))
local vib=tib>0 and lib*(uib/tib-1)or(qib or 0)
local wib=mib[nib+2]
if wib and nib+1<mib.max and wib.cd>0 and sib.cd>0 and tib>0 then
local xib=lib*((wib.damage/wib.cd)/tib-1)
local yib=oib+wib.cost*pib
if xib/yib>vib/oib then
vib=vib+(xib/yib*oib-vib)*0.5
end
end
local zib=(sib.range or 0)>(rib.range or 0)and(1+((sib.range-rib.range)/math.max(1,rib.range)))or 1
return math.max(0,vib)*zib
end
function eb.dpsFor(Aib,Bib)
if Bib<=0 then
return 0
end
local Cib={}
for Dib,Eib in ipairs(Aib)do
if not Eib.farm and Eib.gain>0 then
table.insert(Cib,Eib)
end
end
table.sort(Cib,function(Fib,Gib)
return Fib.gain/Fib.cost>Gib.gain/Gib.cost
end)
local Hib,Iib=0,0
for Jib,Kib in ipairs(Cib)do
if Bib<=0 then
break
end
Iib=Kib.gain/Kib.cost
local Lib=math.min(1,Bib/Kib.cost)
Hib=Hib+Kib.gain*Lib
Bib=Bib-Kib.cost*Lib
end
return Hib+math.max(0,Bib)*Iib*0.7
end
function eb.shieldDps(Mib,Nib,Oib,Pib,Qib,Rib,Sib)
if(Pib or 0)<=0 or(Mib or 0)<=0 or(Qib or 0)<=0 then
return Mib or 0
end
Nib,Oib,Rib=math.max(0.3,Nib or 2),math.max(1,Oib or 1),Rib or 1
local Tib=Mib*Rib*Nib/Oib
