local ejb=eb.shieldDps(Wib,(tonumber(Xib.cd)or 2)*(_ib or 1),cjb.n,Yib,Zib,ajb,cjb.hits)
local fjb=math.max(0,((tonumber(Xib.range)or 0)-(tonumber(Vib.range)or 0))/math.max(1,tonumber(Vib.range)or 1))
return math.max(0,ejb-djb)+djb*fjb
