end
end
for SHb=1,math.min(4,#NHb)do
table.insert(LHb,NHb[SHb])
end
for THb=1,math.min(2,#OHb)do
table.insert(LHb,OHb[THb])
end
for UHb=1,math.min(3,#CHb)do
