local nZb,oZb=gZb[mZb-1],gZb[mZb]
local pZb=(oZb-nZb).Magnitude
local qZb=math.max(1,math.floor(pZb/2))
for rZb=0,qZb-1 do
local sZb=nZb:Lerp(oZb,rZb/qZb)
table.insert(bb.samples,{pos=sZb,prog=(lZb+pZb*rZb/qZb)/math.max(1,jZb),lane=eZb.Name})
end
lZb=lZb+pZb
end
if gZb[#gZb]then
table.insert(bb.samples,{pos=gZb[#gZb],prog=1,lane=eZb.Name})
end
