local Sic,Tic=(tonumber(Nic.wins)or 0)/Qic,(tonumber(Oic.wins)or 0)/Ric
if not Pic and Tic>=0.5 then
if Sic+0.25<Tic and(Qic>=2 or(Sic==0 and Tic>=0.9 and Ric>=3))then
return string.format(eEd[3644],tonumber(Nic.wins)or 0,Qic,Qic==1 and eEd[666]or eEd[1589],tonumber(Oic.wins)or 0,Ric)
end
local Uic,Vic=bb.labMedian(Nic.sec),bb.labMedian(Oic.sec)
if Uic and Vic and Uic>Vic*1.10 and(#Nic.sec>=2 or Uic>Vic*1.25)then
