local tjc,ujc=U.flat(qjc:GetPivot().Position),rjc.range.Value
if kjc(sjc)and not V.toggleOf(sjc)then
njc=njc+1
table.insert(ojc,{p=tjc,r=ujc})
else
for vjc,wjc in ipairs(bb.samples)do
if(U.flat(wjc.pos)-tjc).Magnitude<=ujc then
ljc,mjc=math.min(ljc,wjc.prog),math.max(mjc,wjc.prog)
end
end
end
end
end
if mjc<=ljc then
ljc,mjc=0.75,0.98
end
local xjc=(jjc or njc)+1
local yjc=({ljc,mjc,(ljc+mjc)/2,ljc-(mjc-ljc)/2})[xjc]
if not yjc then
return nil
end
local zjc=V.range(ijc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Ajc={}
for Bjc,Cjc in ipairs(bb.cands)do
local Djc,Ejc,Fjc=U.flat(Cjc),0,0
for Gjc,Hjc in ipairs(bb.samples)do
if(U.flat(Hjc.pos)-Djc).Magnitude<=zjc then
Fjc=Fjc+1
if math.abs(Hjc.prog-yjc)<=0.05 then
Ejc=Ejc+1
local Ijc=U.flat(Hjc.pos)
for Jjc,Kjc in ipairs(ojc)do
if(Ijc-Kjc.p).Magnitude<=Kjc.r then
Ejc=Ejc-0.5
break
end
end
end
end
end
if Ejc>0 then
table.insert(Ajc,{pos=Cjc,sc=Ejc,cov=Fjc})
end
if Bjc%60==0 then
task.wait()
end
end
table.sort(Ajc,function(Ljc,Mjc)
return Ljc.sc>Mjc.sc
end)
for Njc,Ojc in ipairs(Ajc)do
local Pjc=bb.valid(Ojc.pos,ijc.data)
if Pjc then
F.log(1,eEd[3574],string.format(eEd[3653],V.name(ijc.id),bb.CONTROL_WORDS[xjc],math.floor(yjc*100+0.5)))
return Pjc,Ojc.cov,yjc
end
if Njc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(Qjc)
