local Xjc=Wjc._stats
local Yjc=Xjc.id.Value
if Xjc:FindFirstChild(eEd[1908])and not V.isFarm(Yjc)and not V.allyBuff(Yjc)and Yjc~=Qjc.id then
local Zjc,_jc=pcall(bb.liveDps,Wjc,Yjc)
_jc=Zjc and tonumber(_jc)or 0
if _jc>0 then
table.insert(Tjc,{p=U.flat(Wjc:GetPivot().Position),r=Xjc.range.Value,d=_jc})
Ujc=Ujc+_jc
end
end
end
if#Tjc==0 or Ujc<=0 then
return nil
end
local akc={}
for bkc,ckc in ipairs(bb.samples)do
local dkc,ekc=U.flat(ckc.pos),0
for fkc,gkc in ipairs(Tjc)do
if(dkc-gkc.p).Magnitude<=gkc.r then
ekc=ekc+gkc.d
end
end
akc[bkc]=ekc/Ujc
end
local hkc=V.range(Qjc.u,math.min(tonumber(Sjc)or 0,3,V.rows(Qjc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local ikc,jkc,kkc
