for qkc,rkc in ipairs(bb.samples)do
if(U.flat(rkc.pos)-nkc).Magnitude<=hkc then
okc=okc+akc[qkc]
pkc=pkc+1
end
end
if okc>0 and(not jkc or okc>jkc)then
local skc=bb.valid(mkc,Qjc.data)
if skc then
ikc,jkc,kkc=skc,okc,pkc
end
