end
function bb.bestSpot(tkc,ukc,vkc)
if bb.hybridHill and not tkc._hillTry and type(tkc.data)==eEd[1741]and tkc.data.hybrid_placement and not tkc.data.hill_unit then
local wkc=setmetatable({data=bb.hillData(tkc.data),_hillTry=true},{__index=tkc})
local xkc,ykc,zkc=pcall(bb.bestSpot,wkc,ukc,vkc)
if xkc and ykc then
return ykc,zkc
end
end
if bb.focus and not ukc and not vkc and not V.allyBuff(tkc.id)then
local Akc,Bkc=bb.focusSpot(tkc)
if Akc then
return Akc,Bkc
end
end
if not ukc and not vkc and not(bb.depth and bb.depth.leak)then
local Ckc,Dkc,Ekc=pcall(bb.controlSpot,tkc)
if Ckc and Dkc then
return Dkc,Ekc
end
local Fkc,Gkc,Hkc=pcall(bb.holdSpot,tkc)
if Fkc and Gkc then
return Gkc,Hkc
end
end
local Ikc=bb.depth and bb.depth.leak
if bb.layout and bb.layout[tkc.id]and not ukc and not vkc then
local Jkc=false
for Kkc,Lkc in ipairs(bb.mine or{})do
local Mkc=Lkc._stats:FindFirstChild(eEd[3634])
if Mkc and Mkc.Value==tkc.uuid then
Jkc=true
break
end
end
if not Jkc then
for Nkc,Okc in ipairs(bb.layout[tkc.id])do
local Pkc=bb.valid(Okc,tkc.data)
if Pkc and Ikc then
local Qkc,Rkc,Skc=false,U.flat(Pkc),V.range(tkc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Tkc=bb.depth and bb.depth.leakLane and tostring(bb.depth.leakLane)or nil
for Ukc,Vkc in ipairs(bb.samples)do
if Vkc.prog>=Ikc+0.02 and(not Tkc or tostring(Vkc.lane)==Tkc)and(U.flat(Vkc.pos)-Rkc).Magnitude<=Skc then
Qkc=true
break
end
end
if not Qkc then
Pkc=nil
end
end
if Pkc then
bb.layoutUsed=bb.layoutUsed or{}
bb.layoutUsed[tkc.id]=Pkc
return Pkc,bb.cover(Pkc,V.range(tkc.u,math.min(3,V.rows(tkc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1))
end
end
end
end
local Wkc=tkc.data
local Xkc=bb.depth
local Ykc
if vkc then
Ykc=1
for Zkc,_kc in ipairs(bb.mine or{})do
