local hlc=(bb.kind==eEd[1761]or bb.style==eEd[3115]or bb.style==eEd[3116])and not ukc and not(Xkc and Xkc.leak)and not V.isFarm(tkc.id)and V.range(tkc.u,V.rows(tkc.id).max)*flc or nil
local ilc=V.allyBuff(tkc.id)
if bb.killZone()and not ukc and not vkc and not ilc and not(Xkc and Xkc.leak)and not V.isFarm(tkc.id)then
local jlc=hlc or glc
local klc={}
for llc,mlc in ipairs(bb.mine or{})do
local nlc=mlc._stats
local olc=nlc.id.Value
if not V.isFarm(olc)and not V.allyBuff(olc)and nlc:FindFirstChild(eEd[1908])then
