slc=slc+1
end
end
plc[qlc]=slc
end
local wlc,xlc,ylc
local zlc=0
for Alc,Blc in ipairs(bb.cands)do
local Clc=bb.valid(Blc,Wkc)
zlc=zlc+1
if zlc%40==0 then
task.wait()
end
if Clc then
local Dlc,Elc,Flc=U.flat(Clc),0,0
for Glc,Hlc in ipairs(bb.samples)do
if(U.flat(Hlc.pos)-Dlc).Magnitude<=jlc then
Flc=Flc+1
if Hlc.prog>=0.6 then
Elc=Elc+(Hlc.prog-0.5)*(1+plc[Glc])
