end
end
if bb.style==eEd[3116]and not ukc and not vkc and not ilc and not(Xkc and Xkc.leak)and not V.isFarm(tkc.id)then
local Ilc=hlc or glc
local Jlc,Klc,Llc
local Mlc=0
for Nlc,Olc in ipairs(bb.cands)do
local Plc=bb.valid(Olc,Wkc)
