end
end
local Vlc=bb.infinite and bb.trainee and not vkc and tkc.uuid~=bb.trainee and not V.isFarm(tkc.id)and not ilc and not ukc and not(Xkc and Xkc.leak)and(bb.pressure or 0)<O.dangerReach and hb.ZONE or nil
local Wlc=Vlc and V.range(tkc.u,V.rows(tkc.id).max)or nil
local Xlc,Ylc=V.types(tkc.id)
local Zlc=ilc and{}or bb.fieldBuffers()
local _lc,amc={},0
if ilc then
_lc=bb.buffShort(ilc)
for bmc,cmc in ipairs(_lc)do
amc=amc+cmc.dps
end
end
local dmc=O.community and not Ykc and N.TIPS[tkc.id]
local emc=((dmc and dmc.spot==eEd[1729])or(not Ykc and bb.needLastLine(tkc)))and not(Xkc and Xkc.leak)
local fmc=not(Ykc or ukc or ilc)and bb.mergeSpot(tkc)
local gmc=fmc and V.range(tkc.u,0)*0.7
local hmc,imc
if ukc and V.isFarm(tkc.id)then
hmc,imc=bb.farmMergeSpot(tkc)
imc=hmc and imc*0.8
end
local jmc=ukc and not hmc and bb.random and V.isFarm(tkc.id)and bb.farmMergeOk()and{}or nil
local kmc=bb.cands
local lmc,mmc=hmc or fmc,hmc and imc or gmc
if lmc and mmc and mmc>0 then
kmc=table.clone(bb.cands)
for nmc,omc in ipairs({0.5,0.7,0.9})do
for pmc=0,11 do
local qmc=pmc*math.pi/6
table.insert(kmc,lmc+Vector3 .new(math.cos(qmc),0,math.sin(qmc))*mmc*omc)
end
end
end
local rmc,smc,tmc
local umc=0
local vmc=P.maps[bb.mapKey()]and P.maps[bb.mapKey()].dens
for wmc,xmc in ipairs(kmc)do
local ymc=bb.valid(xmc,Wkc)
umc=umc+1
if umc%40==0 then
task.wait()
end
if ymc then
local zmc
if ukc then
zmc= -bb.cover(ymc,glc)
elseif Ykc then
zmc=0
local Amc=U.flat(ymc)
for Bmc,Cmc in ipairs(bb.samples)do
if(U.flat(Cmc.pos)-Amc).Magnitude<=glc then
zmc=zmc+(Cmc.prog<=Ykc+0.05 and 1 or 0.1)
end
end
elseif Vlc then
zmc=0
local Dmc=U.flat(ymc)
for Emc,Fmc in ipairs(bb.samples)do
local Gmc=(U.flat(Fmc.pos)-Dmc).Magnitude
if Fmc.prog<Vlc then
if Gmc<=Wlc then
zmc=zmc-2
end
elseif Gmc<=glc then
zmc=zmc+1
end
end
elseif emc then
zmc=0
local Hmc=U.flat(ymc)
for Imc,Jmc in ipairs(bb.samples)do
if(U.flat(Jmc.pos)-Hmc).Magnitude<=glc then
zmc=zmc+Jmc.prog*Jmc.prog
end
end
elseif ilc and amc>0 then
local Kmc=0
for Lmc,Mmc in ipairs(_lc)do
local Nmc=(U.flat(Mmc.pos)-U.flat(ymc)).Magnitude
if Nmc<=glc then
Kmc=Kmc+Mmc.dps*(1.1-0.1*Nmc/math.max(1,glc))
end
end
zmc=Kmc/amc*100+bb.cover(ymc,glc,true)*0.05
else
local Omc=bb.cover(ymc,glc,true,Xkc)
if hlc then
Omc=bb.cover(ymc,hlc)+Omc*0.25
end
zmc=Omc+(vmc and 0 or(1-bb.progressAt(ymc))*0.5)
local Pmc=0
for Qmc,Rmc in ipairs(Zlc)do
local Smc=Rmc.b.types[Ylc]
if Smc and(U.flat(Rmc.pos)-U.flat(ymc)).Magnitude<=Rmc.range then
Pmc=math.max(Pmc,math.min(Smc,Pmc+Smc*Rmc.b.uptime))
end
end
zmc=zmc*(1+Pmc)
end
if fmc and(U.flat(fmc)-U.flat(ymc)).Magnitude<=gmc then
zmc=zmc+1e6
end
if hmc and(U.flat(hmc)-U.flat(ymc)).Magnitude<=imc then
zmc=zmc+1e6
end
if jmc then
table.insert(jmc,{p=ymc,sc=zmc})
end
if not smc or zmc>smc then
rmc,smc,tmc=ymc,zmc,bb.cover(ymc,glc)
end
end
end
if ilc and#_lc>0 and rmc then
local Tmc=false
for Umc,Vmc in ipairs(_lc)do
if(U.flat(Vmc.pos)-U.flat(rmc)).Magnitude<=glc then
Tmc=true
break
end
end
if not Tmc then
return nil,0
end
end
if jmc and#jmc>0 then
table.sort(jmc,function(Wmc,Xmc)
return Wmc.sc>Xmc.sc
end)
for Ymc=1,math.min(15,#jmc)do
local Zmc,_mc=jmc[Ymc].p,0
for anc=0,7 do
local bnc=anc*math.pi/4
if bb.valid(Zmc+Vector3 .new(math.cos(bnc),0,math.sin(bnc))*5,Wkc)then
_mc=_mc+1
end
if _mc>=2 then
break
end
end
if _mc>=2 then
return Zmc,bb.cover(Zmc,glc)
end
end
end
return rmc,tmc or 0
end
function bb.lookAt(cnc)
local dnc,enc=math.huge,nil
for fnc,gnc in ipairs(bb.samples)do
local hnc=(U.flat(gnc.pos)-U.flat(cnc)).Magnitude
if hnc<dnc then
dnc,enc=hnc,gnc.pos
end
end
local jnc=enc and U.flat(enc-cnc)or Vector3 .new(0,0,-1)
return jnc.Magnitude>0.01 and jnc.Unit or Vector3 .new(0,0,-1)
end
function bb.place(knc,lnc)
local mnc=V.isFarm(knc.id)
local nnc,onc=bb.bestSpot(knc,mnc or(bb.random and V.idol(knc.id)),(bb.trainee~=nil and knc.uuid==bb.trainee)or V.ENTRY[knc.id]==true or(bb.studyEntry==true and knc.id==bb.trialId))
if not nnc then
bb.noSpot[knc.uuid]=(bb.noSpot[knc.uuid]or 0)+1
F.status(eEd[3568],eEd[3656]..V.name(knc.id))
return false
end
local pnc=bb.money()
local qnc,rnc=F.request(eEd[3657],eEd[3658],knc.uuid,N.Util.CFramePLV(nnc,bb.lookAt(nnc)))
if qnc and rnc then
bb.spent=bb.spent+(knc.data.cost or 0)
table.insert(bb.actions,string.format(eEd[3659],V.name(knc.id)))
F.log(1,eEd[3574],string.format(eEd[3660],V.name(knc.id),bb.spotKey(nnc),onc,lnc))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=knc.id,x=math.floor(nnc.X),z=math.floor(nnc.Z),cover=math.floor((onc or 0)+0.5),why=tostring(lnc):sub(1,90)})
F.status(eEd[3568],string.format(eEd[3661],V.name(knc.id),lnc))
bb.placedAt=bb.placedAt or{}
bb.placedAt[knc.uuid]=(bb.placedAt[knc.uuid]or 0)+1
return true
end
if pnc>=(knc.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[knc.uuid]=(bb.placeFail[knc.uuid]or 0)+1
if bb.placeFail[knc.uuid]>=2 then
bb.noSpot[knc.uuid]=3
F.log(1,eEd[3574],string.format(eEd[3662],V.name(knc.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if qnc and pnc>=(knc.data.cost or 0)and not bb.random then
local snc=bb.spotKey(nnc)
bb.refused[snc]=true
local tnc=bb.mapKey()
P.blocked[tnc]=P.blocked[tnc]or{}
if not bb.refusedRun[snc]then
P.blocked[tnc][snc]=(tonumber(P.blocked[tnc][snc])or 0)+1
bb.refusedRun[snc]=true
end
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[knc.uuid]=(bb.unitRefusals[knc.uuid]or 0)+1
if bb.unitRefusals[knc.uuid]>=3 then
local unc=math.max(1,bb.count(knc.uuid))
if P.caps[knc.uuid]~=unc then
P.caps[knc.uuid]=unc
F.log(1,eEd[3574],string.format(eEd[3663],V.name(knc.id),unc))
end
end
F.log(2,eEd[3574],eEd[3664]..snc..eEd[2384]..V.name(knc.id))
F.saveSoon()
end
return false
end
function bb.count(vnc)
local wnc=0
for xnc,ync in ipairs({workspace._UNITS,workspace:FindFirstChild(eEd[3665])})do
if ync then
for znc,Anc in ipairs(ync:GetChildren())do
local Bnc=Anc:FindFirstChild(eEd[1803])
if Bnc and Bnc:FindFirstChild(eEd[3634])and Bnc.player.Value==M and Bnc.uuid.Value==vnc then
wnc=wnc+1
end
end
end
end
return wnc
end
function bb.measure()
local Cnc,Dnc=bb.calRun,bb.info
if not(Cnc and Dnc)then
return
end
pcall(bb.sampleHelpers)
local Enc=U.now()
local Fnc=bb.wave()
local Gnc=bb.money()
if not Cnc.start and Gnc>0 and#bb.mine==0 then
Cnc.start=Gnc
end
if Fnc~=Cnc.lastW then
if bb.trialId and Fnc>0 then
bb.trialTrace=bb.trialTrace or{}
local Hnc,Inc,Jnc,Knc=0,{},0,0
for Lnc,Mnc in ipairs(bb.mine)do
local Nnc=Mnc._stats
if Nnc.id.Value==bb.trialId then
Hnc=Hnc+1
table.insert(Inc,tostring(Nnc.upgrade.Value))
elseif not V.isFarm(Nnc.id.Value)then
Knc=Knc+1
end
end
pcall(bb.sampleHelpers,true)
for Onc,Pnc in pairs(bb.ownDealt)do
if Pnc.id==bb.trialId then
Jnc=Jnc+Pnc.v
end
end
local Qnc=0
for Rnc,Snc in pairs(bb.helperDealt)do
if Snc.owner==bb.trialId then
Qnc=Qnc+Snc.v
end
end
table.insert(bb.trialTrace,string.format(eEd[3666],Fnc,Enc-(bb.startT or Enc),Gnc,table.concat(Inc,eEd[2446]),Knc,Jnc+Qnc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[Fnc-1]or 0,bb.teamDps or 0))
end
if Cnc.lastW and Cnc.lastW>0 and Cnc.lastWT then
table.insert(Cnc.waveSec,Enc-Cnc.lastWT)
end
if Cnc.paidT and Fnc>0 and Enc-Cnc.paidT<15 then
table.insert(Cnc.skip,Enc-Cnc.paidT)
end
Cnc.paidT=nil
if Fnc>0 then
Cnc.alive[tostring(Fnc)]=bb.hpAliveRaw or 0
end
Cnc.lastW,Cnc.lastWT=Fnc,Enc
end
local Tnc=workspace:FindFirstChild(eEd[3667])
if Tnc and Fnc>0 then
Cnc.timer[tostring(Fnc)]=math.max(Cnc.timer[tostring(Fnc)]or 0,tonumber(Tnc.Value)or 0)
end
local Unc=Gnc-(bb.lastMoneyR or Gnc)
bb.lastMoneyR=Gnc
bb.incomeLog=bb.incomeLog or{}
if Unc>0 then
table.insert(bb.incomeLog,{t=Enc,y=Unc})
end
while bb.incomeLog[1]and Enc-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local Vnc=0
for Wnc,Xnc in ipairs(bb.incomeLog)do
Vnc=Vnc+Xnc.y
end
local Ync=math.min(30,Enc-(bb.startT or Enc))
bb.incomeRate=Ync>=8 and Vnc/Ync or nil
for Znc,_nc in ipairs(bb.enemies)do
local aoc=_nc.m
local boc=bb.track[aoc]
if not boc then
local coc=aoc._stats
local doc=aoc:FindFirstChildOfClass(eEd[3492])
local eoc=Dnc.cfgById[coc.id.Value]
local foc=eoc and fb.baseStats(Dnc,eoc)
if doc and foc and Fnc>0 then
local goc=foc*Dnc.hpRaw*fb.waveScale(Dnc,Fnc,Dnc.list[Fnc])
if goc>0 and doc.MaxHealth>0 then
table.insert(Cnc.hp,doc.MaxHealth/goc)
end
end
bb.track[aoc]={t=Enc,p=_nc.prog,sp=(coc:FindFirstChild(eEd[3668])and tonumber(coc.speed.Value))or 1}
if doc and doc.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+doc.MaxHealth
end
if Fnc>0 then
Cnc.spawn[tostring(Fnc)]=(Cnc.spawn[tostring(Fnc)]or 0)+1
Cnc.spawnLast[tostring(Fnc)]=Enc-(Cnc.lastWT or Enc)
end
elseif not boc.done and Enc-boc.t>=15 then
boc.done=true
local hoc=(_nc.prog-boc.p)/(Enc-boc.t)/math.max(0.1,boc.sp)
if hoc>0.001 and _nc.prog<0.95 then
table.insert(Cnc.walk,hoc)
end
end
end
local ioc=0
for joc,koc in ipairs(bb.mine)do
local loc=koc._stats:FindFirstChild(eEd[3669])
if loc then
ioc=ioc+loc.Value
end
end
Cnc.potSum=Cnc.potSum or 0
if Cnc.lastDealtT then
local moc=Enc-Cnc.lastDealtT
local noc=0
Cnc.potBy=Cnc.potBy or{}
for ooc,poc in ipairs(bb.mine)do
local qoc=poc._stats
local roc=qoc.id.Value
if not V.isFarm(roc)and qoc:FindFirstChild(eEd[3670])and qoc.target.Value~=nil then
local soc,toc=pcall(bb.liveDps,poc,roc)
if soc and toc then
noc=noc+toc*moc
local uoc=toc/math.max(0.5,V.nudge(roc))
local voc,woc=pcall(function()
return V.passive(roc).mark
end)
if voc and woc and qoc:FindFirstChild(eEd[1905])then
uoc=uoc+(tonumber(woc.dot)or 0)*qoc.damage.Value
end
Cnc.potBy[roc]=(Cnc.potBy[roc]or 0)+uoc*moc
end
end
end
Cnc.potWin=(Cnc.potWin or 0)+noc
if Enc-(Cnc.winT or Enc)>=5 then
local xoc=ioc-(Cnc.winDealt or ioc)
if Cnc.potWin>0 and xoc>=0 then
Cnc.dealtSum=(Cnc.dealtSum or 0)+xoc
Cnc.potSum=Cnc.potSum+Cnc.potWin
end
Cnc.winT,Cnc.winDealt,Cnc.potWin=Enc,ioc,0
end
end
if not Cnc.winT then
Cnc.winT,Cnc.winDealt=Enc,ioc
end
Cnc.lastDealtT=Enc
if Fnc~=Cnc.dpsW and Fnc>0 then
Cnc.dpsAt[tostring(Fnc)]=bb.teamDps or 0
Cnc.dpsW=Fnc
end
local yoc=math.min(1,Enc-(Cnc.densT or Enc))
Cnc.densT=Enc
for zoc,Aoc in ipairs(bb.enemies)do
local Boc=math.min(fb.BINS,math.floor(Aoc.prog*fb.BINS)+1)
Cnc.dens[Boc]=(Cnc.dens[Boc]or 0)+yoc
end
local Coc=workspace._BASES.player:FindFirstChild(eEd[3671])
local Doc=Coc and Coc:FindFirstChild(eEd[3672])
local Eoc=Doc and Doc:FindFirstChildOfClass(eEd[3492])
if Eoc then
Cnc.baseHp=math.max(Cnc.baseHp or 0,Eoc.MaxHealth)
local Foc=0
for Goc,Hoc in ipairs(bb.enemies)do
if Hoc.prog>=0.97 then
local Ioc=Hoc.m:FindFirstChildOfClass(eEd[3492])
Foc=Foc+(Ioc and Ioc.MaxHealth or Hoc.hp)
end
end
if Cnc.lastBase and Eoc.Health<Cnc.lastBase and Foc>0 and Cnc.lastBaseT then
table.insert(Cnc.baseRel,(Cnc.lastBase-Eoc.Health)/math.max(0.1,Enc-Cnc.lastBaseT)/Foc)
end
Cnc.lastBase,Cnc.lastBaseT=Eoc.Health,Enc
end
end
function bb.recordMap()
local Joc=bb.mapKey()
local Koc=P.maps[Joc]
if Koc and Koc.v==1 and Koc.laneV and(Koc.densN or 0)==(Koc.binsDensN or 0)then
return
end
if Koc and Koc.v==1 and Koc.laneV and(Koc.densN or 0)>5 and(Koc.binsDensN or 0)>=5 then
return
end
local Loc={override_hitbox_radius=1.75}
local Moc={hill_unit=true,override_hitbox_radius=1.75}
local Noc,Ooc={},false
for Poc,Qoc in ipairs(bb.cands)do
local Roc=bb.valid(Qoc,Loc)
if Roc then
table.insert(Noc,Roc)
end
if not Ooc and bb.valid(Qoc,Moc)then
Ooc=true
end
if Poc%30==0 then
task.wait()
end
end
local Soc,Toc={},{}
local Uoc=fb.laneList(bb.samples)
for Voc=5,60,5 do
local Woc,Xoc
for Yoc,Zoc in ipairs(Noc)do
local _oc=bb.cover(Zoc,Voc,true)
if not Xoc or _oc>Xoc then
Woc,Xoc=Zoc,_oc
end
end
if Woc then
local apc,bpc={},{}
for cpc=1,fb.BINS do
