function bb.learn()
local JAc=bb.calRun and bb.calRun.potBy
if type(JAc)~=eEd[1741]then
return
end
pcall(bb.sampleHelpers,true)
local KAc={}
for LAc,MAc in pairs(bb.ownDealt or{})do
if not V.isFarm(MAc.id)then
KAc[MAc.id]=(KAc[MAc.id]or 0)+(tonumber(MAc.v)or 0)
end
end
for NAc,OAc in pairs(bb.helperDealt or{})do
if OAc.owner and V.SUMMONER[OAc.owner]then
KAc[OAc.owner]=(KAc[OAc.owner]or 0)+(tonumber(OAc.v)or 0)
end
end
local PAc,QAc=0,0
for RAc,SAc in pairs(JAc)do
if SAc>0 then
PAc=PAc+(KAc[RAc]or 0)
QAc=QAc+SAc
end
end
if PAc<=0 or QAc<=0 then
return
end
local TAc=PAc/QAc
bb.lastEff={}
for UAc,VAc in pairs(JAc)do
if VAc>0 and VAc/QAc>0.02 then
local WAc=P.learn[UAc]or{eff=1,n=0,v=3}
if(tonumber(WAc.v)or 0)<3 then
WAc.eff,WAc.v=(tonumber(WAc.eff)or 1)*V.effRescale(UAc),3
end
local XAc=math.max(0.02,0.25*math.sqrt(30/(30+WAc.n)))
local YAc=U.clamp(((KAc[UAc]or 0)/VAc)/TAc,0.2,6)
bb.lastEff[UAc]=math.floor(YAc*1000+0.5)/1000
WAc.eff=WAc.eff+(YAc-WAc.eff)*XAc
WAc.n=WAc.n+1
P.learn[UAc]=WAc
end
end
local ZAc=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if ZAc and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==eEd[1741]and P.mapLearn or{}
local _Ac=type(P.mapLearn[ZAc])==eEd[1741]and P.mapLearn[ZAc]or{}
for aBc,bBc in pairs(bb.lastEff)do
local cBc=type(_Ac[aBc])==eEd[1741]and _Ac[aBc]or{eff=bBc,n=0}
local dBc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(cBc.n)or 0))))
cBc.eff=(tonumber(cBc.n)or 0)==0 and bBc or((tonumber(cBc.eff)or bBc)+(bBc-(tonumber(cBc.eff)or bBc))*dBc)
cBc.n=(tonumber(cBc.n)or 0)+1
_Ac[aBc]=cBc
end
_Ac._at=os.time()
P.mapLearn[ZAc]=_Ac
if U.count(P.mapLearn)>80 then
local eBc,fBc
for gBc,hBc in pairs(P.mapLearn)do
if not fBc or(tonumber(hBc._at)or 0)<fBc then
eBc,fBc=gBc,tonumber(hBc._at)or 0
end
end
P.mapLearn[eBc]=nil
end
end
end
