bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(NGc,OGc)
local PGc=(OGc.t or 0)-(NGc.t or 0)
if PGc<bb.BASE_WIN-1 then
return false
end
local QGc=((tonumber(NGc.base)or 0)-(tonumber(OGc.base)or 0))/PGc
if QGc<=0 or(tonumber(OGc.base)or 0)<=0 then
return false
end
local RGc=OGc.base/QGc
local SGc,TGc=0,0
local UGc,VGc=NGc.foes or{},OGc.foes or{}
for WGc,XGc in pairs(VGc)do
if XGc.prog>=bb.BASE_END then
SGc=SGc+XGc.hp
local YGc=UGc[WGc]
if YGc then
TGc=TGc+math.max(0,YGc.hp-XGc.hp)
end
end
end
for ZGc,_Gc in pairs(UGc)do
if _Gc.prog>=bb.BASE_END and not VGc[ZGc]then
TGc=TGc+_Gc.hp
end
end
if SGc<=0 then
return false
end
local aHc=TGc/PGc
local bHc=aHc>0 and SGc/aHc or math.huge
local cHc={baseTime=RGc,loss=QGc,atEnd=SGc,rate=aHc,killTime=bHc}
return RGc<bb.BASE_SOON and bHc>RGc*bb.BASE_MARGIN,cHc
end
