local icd=fcd.obj.AbsolutePosition.Y-hcd.AbsolutePosition.Y
local jcd,kcd=fcd.obj.AbsoluteSize.Y,hcd.AbsoluteWindowSize.Y
if icd<0 then
hcd.CanvasPosition=Vector2 .new(0,math.max(0,hcd.CanvasPosition.Y+icd-10))
elseif icd+jcd>kcd then
hcd.CanvasPosition=Vector2 .new(0,hcd.CanvasPosition.Y+icd+jcd-kcd+10)
end
end
