function mb.K.key(lcd,mcd)
local ncd,ocd,pcd=mb.K,mb.Win,Enum.KeyCode
if ncd.cur and not(ncd.cur.obj and ncd.cur.obj.Parent and ncd.shown(ncd.cur.obj))then
ncd.setFocus(nil)
end
if ncd.cur and ncd.cur.listKey and ncd.cur.listKey(lcd)then
return true
end
if lcd==pcd.PageUp or lcd==pcd.PageDown then
local qcd={}
for rcd,scd in pairs(ocd._tabs)do
table.insert(qcd,{name=rcd,y=scd.btn.AbsolutePosition.Y,on=scd.page.Visible})
end
table.sort(qcd,function(tcd,ucd)
return tcd.y<ucd.y
end)
local vcd=1
for wcd,xcd in ipairs(qcd)do
if xcd.on then
vcd=wcd
end
end
vcd=(vcd-1+(lcd==pcd.PageDown and 1 or-1))% #qcd+1
ncd.setFocus(nil)
ocd:SelectTab(qcd[vcd].name)
return true
end
if lcd==pcd.Tab or lcd==pcd.Down or lcd==pcd.Up then
local ycd=ncd.order()
if#ycd==0 then
return true
end
local zcd=lcd==pcd.Up or(lcd==pcd.Tab and mcd)
local Acd=table.find(ycd,ncd.cur)
if not Acd then
Acd=zcd and#ycd or 1
else
Acd=(Acd-1+(zcd and-1 or 1))% #ycd+1
end
ncd.setFocus(ycd[Acd])
return true
end
if not ncd.cur then
return false
end
if lcd==pcd.Return or lcd==pcd.KeypadEnter or lcd==pcd.Space then
if ncd.cur.activate then
ncd.cur.activate()
end
return true
end
if lcd==pcd.Left or lcd==pcd.Right then
if ncd.cur.adjust then
ncd.cur.adjust(lcd==pcd.Right and 1 or-1)
end
return true
end
if lcd==pcd.Escape then
ncd.setFocus(nil)
return true
end
return false
end
function mb.K.keys(Bcd)
local Ccd=mb.K
local Dcd,Ecd,Fcd=game:GetService(eEd[4425]),game:GetService(eEd[4349]),game:GetService(eEd[4426])
local Gcd=Enum.KeyCode
Ccd.keyName=eEd[4427]..(tostring(mb.TITLE):gsub(eEd[4428],eEd[666]))
function Ccd.over()
local Hcd=Bcd._main
if not(Hcd and Hcd.Parent and Hcd.Visible)then
return false
end
local Icd=Ecd:GetMouseLocation()
local Jcd=Fcd:GetGuiInset()
local Kcd,Lcd=Icd.X,Icd.Y-Jcd.Y
local Mcd,Ncd=Hcd.AbsolutePosition,Hcd.AbsoluteSize
return Kcd>=Mcd.X and Kcd<=Mcd.X+Ncd.X and Lcd>=Mcd.Y and Lcd<=Mcd.Y+Ncd.Y
end
Dcd:BindActionAtPriority(Ccd.keyName,function(Ocd,Pcd,Qcd)
if Pcd~=Enum.UserInputState.Begin then
return Enum.ContextActionResult.Pass
end
if Ecd:GetFocusedTextBox()or not Ccd.over()then
return Enum.ContextActionResult.Pass
end
local Rcd,Scd=pcall(Ccd.key,Qcd.KeyCode,Ecd:IsKeyDown(Gcd.LeftShift)or Ecd:IsKeyDown(Gcd.RightShift))
return(Rcd and Scd)and Enum.ContextActionResult.Sink or Enum.ContextActionResult.Pass
end,false,3000,Gcd.Tab,Gcd.Return,Gcd.KeypadEnter,Gcd.Space,Gcd.Left,Gcd.Right,Gcd.Up,Gcd.Down,Gcd.Escape,Gcd.PageUp,Gcd.PageDown)
Bcd._track(Ecd.InputBegan:Connect(function(Tcd)
if Tcd.UserInputType==Enum.UserInputType.MouseButton1 and Ccd.cur then
pcall(Ccd.setFocus,nil)
end
end))
Bcd._screen.Destroying:Connect(function()
pcall(function()
Dcd:UnbindAction(Ccd.keyName)
end)
end)
end
